namespace Aw.Sindri.Host.Commands;

/// <summary>The usage text: one line per verb, then the exit codes.</summary>
internal static class Usage
{
    private static readonly string[] _verbs =
    [
        // ---- one line per verb ----
        "usage: sindri [--headless]           start the control plane if it isn't running, then print its summary",
        "       sindri serve                  run the control plane in the foreground (what 'sindri' starts; launchd target)",
        "       sindri status [--json]        the running control plane's status (exit 1 when it isn't running)",
        "       sindri status --follow [--json]   the status again each time it changes, until Ctrl-C (exit 0), or 1 when Sindri isn't running or stops",
        "       sindri stop                   stop it and release the host lease",
        "       sindri profile validate [--json]",
        "       sindri profile init [--json]   write the default profile when none exists (no repos yet: add one with 'repo add'); refuses when one exists (exit 2); runs without the control plane",
        "       sindri profile set <key> <value> [--json]   set one scalar key of the live profile in place (dotted key, such as context.models.labeling.pick): comments and order stay, the edited file is checked before it is written, and the edit is live at once; refused without the per-start human token or for an agent session (SND-AUTH-002); runs without the control plane",
        "       sindri scrub [--staged | --install-pre-commit [--repo PATH] [--bin PATH]]   redact standard input; --staged scans the staged diff's added lines (exit 1, SND-SCRUB-002, on a finding); --install-pre-commit writes the pre-commit hook that runs it; runs without the control plane",
        "       sindri profile approve [<hash>]   removed (edits apply on save): prints that line and exits 0",
        "       sindri views rebuild [--no-start]   replay the ledger into the views (the fix when they stall); starts the control plane unless --no-start",
        "       sindri queue [--json] [--no-start]   the queue's groups, one line per item; exit 1 while the views rebuild or stall; starts the control plane unless --no-start",
        "       sindri ledger [--after N] [--item X] [--type T] [--max N] [--json] [--no-start]   the audit read: one line per event (a human also sees non-public types), then 'next: N' while more remain; starts the control plane unless --no-start",
        "       sindri sandbox explain <path|host|command> [--plan <file>] [--json]   why a path, host or command is allowed or blocked in the sandbox, and how the owner can change it; reads only the plan file (--plan or AW_SANDBOX_PLAN), no control plane",
        "       sindri sandbox check [--json]   every reason this machine can't confine a Step, each with its fix, or the Steps a Check again would resume; asks the running control plane (exit 0 ready, 1 blocked or not running)",
        "       sindri sandbox show [--plan <file>]   what the sandbox lets a session write, read and reach, then the whole plan; reads only the plan file (--plan or AW_SANDBOX_PLAN), no control plane",
        "       sindri sandbox denials [--run <launchId>] [--since <time|30m|6h|2d>] [--json]   what the sandbox blocked, by target and rule, with the fix for each; asks the running control plane (exit 1 when it is down)",
        "       sindri sandbox exec <launch|run-area> [--json] [-- <command...>]   run a command (a shell without one) in a fresh sandbox built from that launch's plan, as the agent saw it: worktree, ref directories and run directory read-only, a fresh scratch, no launch secret or GitHub token, its own egress, counted against the session cap; an agent session may run it too; exit code is the command's, 2 for usage or a sandbox that can't be made",
        "       sindri sandbox login <claude-code|codex>   sign the agent in to its own home, the one Steps use when sandbox.login.source is separate-login: makes the home, installs the toolkit hooks into it, then runs the agent's sign-in on this terminal; an agent session may run it too; exit code is the sign-in's, 2 for usage or a refusal",
        "       sindri items [--state <s>] [--repo <r>] [--json] [--no-start]   the item list, the oldest first",
        "       sindri item add <title> [--repo <r>] [--no-start]   create an item: 'ITM-… created (sequence N)'",
        "       sindri handoff send <title> [--source <s>] [--repo <r>] [--branch <b>] [--prompt <text> | --prompt-file <file>] [--offer <id>] [--link <url> | --link <label>=<url>]... [--label <l>]... [--json] [--no-start]   hand work to Sindri from this machine: makes an item and keeps the whole prompt, branch, links and labels in its 'item.handoff' event (the prompt may be 65,536 characters, the item body keeps 4,000); --source names the sender (default local); 'ITM-… handed off (offer X, sequence N)'",
        "       sindri item close <item> [--cancelled] [--version <n>] [--no-start]   close an item (id or tracker key) as done, or cancelled; without --version it closes the version it reads first",
        "       sindri projects [--all] [--json] [--no-start]   the Projects page: one line per project (id, state, name, open issues, last activity), then the Finished and Hidden folds and when each source last synced; --all lists every finished project; exit 1 while the views rebuild or stall",
        "       sindri project show <project> [--json] [--no-start]   one project in full, with its links and version (a prj_ id, a linear:project/<id> key or a Linear project url)",
        "       sindri project add [--linear <key>] [--name <text>] [--link <url> | --link <label>=<url>]... [--state <state>] [--notes <text>] [--target <date>] [--json] [--no-start]   put a Linear project (by its linear:project/<id> key) or a hand-made one (by name) on the Projects page: 'prj_… attached: <name> (sequence N)'; --state is backlog, planned, in-progress, paused, done or canceled",
        "       sindri project edit <project> [--version <n>] [--name <text>] [--link <url> | --link <label>=<url>]... [--state <state> | --clear-state] [--notes <text> | --clear-notes] [--target <date> | --clear-target] [--json] [--no-start]   change a project by its prj_ id, at the version `sindri projects` shows (read for you when --version is left out); --link replaces the whole list; a Linear project you lead (linear:project/<id>) takes --notes and --clear-notes only",
        "       sindri project remove <project> [--version <n>] [--json] [--no-start]   take a project off the page (its prj_ id and version)",
        "       sindri project hide <project> [--version <n>] [--json] [--no-start]   hide a Linear project you lead (its linear:project/<id> key and hide version, 0 when never hidden)",
        "       sindri project unhide <project> [--version <n>] [--json] [--no-start]   show a hidden Linear project again",
        "       sindri todos [--done | --all] [--json] [--fence | --no-fence] [--no-start]   your todos: one line per todo (id, due day or -, text, links); --all adds a state column and the removed ones; text is fenced when stdout isn't a terminal unless --no-fence; exit 1 while the views rebuild or stall",
        "       sindri todo show <id> [--json] [--no-start]   one todo: who added and last changed it, and for a todo changed in both places the two versions; <id> is a full id or a unique prefix (td_01jc5a)",
        "       sindri todo add <text> [--due <day>] [--link <ref>]... [--client-id <id>] [--json] [--no-start]   add a todo: 'td_… added (due Fri 2026-11-13)'; a trailing day word in the text (today, tomorrow, fri, 11-10, 2026-11-10) is the due day; --link is an item id, owner/repo#n, a Linear key or a workflow address",
        "       sindri todo edit <id> [--text <text>] [--due <day> | --no-due] [--link <ref>]... [--no-links] [--version <n>] [--json] [--no-start]   change a todo (open ones by id prefix); --link given at all replaces the whole list; without --version it changes the version it reads first (last writer wins)",
        "       sindri todo done|reopen|remove|restore <id> [--version <n>] [--json] [--no-start]   check off an open todo, reopen a done one, remove an open one (soft: 'td_… removed (sindri todo restore td_…)') or bring a removed one back",
        "       sindri todo keep <id> sindri|obsidian [--json] [--no-start]   pick a side of a todo changed in Sindri and in Obsidian: 'td_… kept Obsidian's version; written to the note in 10 s' (an open pick can be undone in the app for 10 s)",
        "       sindri todo note [--json] [--no-start]   the Obsidian todo note's state ('not set' until the note sync ships)",
        "       sindri todo note set <vault> <note> [--json]   set the Obsidian todo note: both fields of todo.obsidian in the live profile in one checked edit (<vault> is one of context.sources.library.vaults, <note> a .md path inside it); live at once, no approval; runs without the control plane; a launched session may run it; exit 0 set or unchanged, 2 SND-TODO-002 or a profile error",
        "       sindri todo note stop [--json]   stop syncing: remove todo.obsidian from the live profile (comments and order stay); the note stays as it is; exit 0 removed or unchanged",
        "       sindri todo note import [--expect <n>] [--dry-run] [--json] [--no-start]   adopt the note's open top-level - [ ] lines as todos (REQ-E6): --dry-run counts them and prints the --expect to pass, writes nothing; --expect <n> imports only when the note still has n importable lines (SND-TODO-409 otherwise); needs todo.obsidian to be set (SND-TODO-002), a note with none to import is SND-TODO-008; a launched session may run it; exit 0 ok, 1 control plane down, 2 refused",
        "       sindri connections [--json] [--no-start]   the connections (name, kind, status) and why one is not connected; the same as 'connection list'",
        "       sindri connection add <service:label> [--preset <p>] [--kind <oauth|mcp|rest|cli>] [--client-id <id>] [--client-secret-env <NAME>] [--key-env <NAME>] [--url <address>] [--scope <s>]... [--json] [--no-start]   add a connection: an oauth one prints the consent URL, opens the browser and waits up to 5 minutes for the callback; a rest or cli one stores the key read from this shell's variable NAME; an mcp one needs --url and takes --key-env or, without a key, signs in through the server's own page (the secret goes to the OS keychain, never the profile or the ledger)",
        "       sindri connection show <service:label> [--json] [--no-start]   one connection: kind, preset, status and its reason, whether a secret is stored; never the token",
        "       sindri connection signin <service:label> [--json] [--no-start]   sign a stored oauth or mcp connection in again (a lapsed refresh, a revoked grant): prints the consent URL, opens the browser and waits up to 5 minutes; the connection keeps its name and settings; a key-based one is SND-CONN-011",
        "       sindri connection test <service:label> [--json] [--no-start]   call the provider's probe URL with the stored credential; exit 1 when it is refused",
        "       sindri connection rename <service:label> <label> [--json] [--no-start]   change the label only (slack:old -> slack:new); the stored secret moves with it; a taken name is SND-CONN-010, an unknown one SND-CONN-001",
        "       sindri connection remove <service:label> [--json] [--no-start]   delete the connection and its stored secret",
        "       sindri open <item> [--agent <id>] [--attach | --resume] [--version <n>] [--no-wait] [--json] [--no-start]   open the item's agent session (claude-code, codex, cursor or an added agent): asks for a launch, waits for the launcher's answer (up to 35 s) and prints how the viewer fared, and the attach command when no window opened; exit 0 started, 1 not running or no answer yet, 2 refused or failed",
        "       sindri request <kind> [--item <item>] <text> [--json] [--no-start]   ask a human (rescope, add-task, note or handback), about an item or none: 'REQ-… filed; DEC-… waits for a human'; it is a session's verb",
        "       sindri requests [--state <s>] [--item <item>] [--json] [--no-start]   the requests, newest first, with their text; exit 1 while the views rebuild or stall",
        "       sindri decisions [--pending | --decided] [--item <item>] [--json] [--no-start]   the decisions: pending oldest first, decided newest first, each with its question and the command that decides it; exit 1 while the views rebuild or stall",
        "       sindri decide <decisionId> <choice> [--note <note>] [--json] [--no-start]   settle a decision (accept or decline)",
        "       sindri needs-you [--json] [--no-start]   what needs a human: decisions, failures, a drifted profile, each with the command that does it; exit 1 while the views rebuild or stall",
        "       sindri services [--json] [--no-start]   each background service: cadence, paused, last run and next slot, and a running job; exit 1 while the views rebuild or stall; starts the control plane unless --no-start",
        "       sindri services run <name> [--detach] [--json] [--no-start]   run a service now as a job and follow it (Ctrl-C cancels the job, a second Ctrl-C leaves); --detach prints the job id and returns; exit 0 succeeded, 1 failed, cancelled or Sindri stopped, 2 refused or invalid",
        "       sindri services pause|resume <name> [--no-start]   stop or restart a service's scheduled runs",
        "       sindri index embed [--detach] [--json] [--no-start]   embed the indexed records that have no meaning vector yet, now, as 'services run index-embed' does and follows it the same way",
        "       sindri index embed pause|resume [--no-start]   stop or restart the index-embed service's scheduled runs (the same as 'services pause|resume index-embed')",
        "       sindri index sync [<source>] [--detach] [--json] [--no-start]   pull new records now: runs the 'index-sync' service as a job and follows it as 'services run' does (every feed ticks; a named source must be one of the feeds); exit 0 succeeded, 1 failed or Sindri stopped, 2 refused or invalid",
        "       sindri library sync [--detach] [--json] [--no-start]   read the design-doc library's folders now: ticks the 'library' record source as a job (same as 'sindri index sync library'; the profile needs a 'context:' section); exit 0 succeeded, 1 failed or Sindri stopped, 2 refused or invalid",
        "       sindri library list [--errors|--near-misses] [--json]   the design-doc library: how many docs, which have errors (file, rule, the fix), the files that look like design docs but aren't read, and any library folder that can't be read; --errors or --near-misses prints only that part; never starts Sindri; exit 0 ok, 1 Sindri stopped, 2 invalid",
        "       sindri library show <doc> [--json]   one design doc by its id: kind, status, title, file, root and scope, and its errors (SND-LIB-404 when none; with two scopes sharing an id, the doc at the lowest path); never starts Sindri; exit 0 ok, 1 Sindri stopped, 2 not found or invalid",
        "       sindri library validate <path|dir> [--root <name>] [--json]   check a file or folder of design docs against the convention here, without Sindri running; --root names the scope the docs share (default 'local'); exit 0 no findings, 1 findings, 2 invalid ('--pr-body', '--repo' and '--docs' are not yet)",
        "       sindri index status [--json]   each record source: where its sync stands (not started, syncing the recent window, usable, complete), its last tick and the code it ended with; reads the running control plane and never starts it; exit 1 while a source ended with a code or Sindri isn't running",
        "       sindri index purge <source>   at a terminal: shows what the source holds (records, chunks, vectors) and deletes it after you type yes; a sync refills only what the source still has; an agent session may run it from a terminal too",
        "       sindri jobs [--state <s>] [--kind <k>] [--json] [--no-start]   the jobs, newest first (states: running, succeeded, failed, cancelled); exit 1 while the views rebuild or stall",
        "       sindri jobs show <jobId> [--json] [--no-start]   one job: who started it, its last 200 lines, how it ended and the command that cancels it",
        "       sindri jobs cancel <jobId> [--no-start]   cancel a running job (SND-JOB-409 when it already ended)",
        "       sindri jobs resume <jobId> [--no-start]   wake a job paused because every model harness hit its usage limit and walk its harnesses again from the first (SND-JOB-003 when it isn't paused for that); exit 2 when it isn't",
        "       sindri launch init [--viewer <name>] [--force] [--stdout]   detect this box's terminal and write launcher.json (0600); a file that exists is refused without --force (exit 1); --stdout writes nothing",
        "       sindri launch probe [--detach] [--json]   check the launch targets again (the Check again control): a job on the running control plane that records launch.probed when what it found changed; follows the job as 'services run' does",
        "       sindri launch show [<id>] [--json]   the merged agent catalog: source, resolved bin, argvHash, whether Steps may run it (SL8) and the profile line that approves an entry that will park",
        "       sindri launch picks [--item X] [--json]   the model each agent run was given and why, oldest first: item, step ('.e1' for a retry), agent, model, who picked it, the reason, tokens, cost and what Jev's pick cost; read-only, needs the control plane running (exit 1 SND-API-001 when it is not)",
        "       sindri agents [--provider <agent>] [--state <s>] [--repo <r>] [--json]   every live agent session on the box: state, repo and host, and the recently ended ones; reads the running control plane and never starts it; exit 1 when it isn't running or a source failed",
        "       sindri agents show <provider>/<id> [--json]   one session in full: host, lane, launch and, at a terminal, directory and state history (SND-SESSION-404 when none)",
        "       sindri agents start --repo <r> --agent claude-code|codex [--prompt <text>] [--worktree] [--act-id <id>] [--json]   start a one-off agent in tmux on Sindri's own tmux server (human only; the control plane must be running); prints the id and the attach command; exit 0 started, 1 refused or not running, 2 usage",
        "       sindri agents worktree remove <actId> [--json]   remove the worktree a start made (git worktree remove, never --force; SND-AGENT-018 when it has changes)",
        "       sindri skills [--json]   the skill blocks the control plane loaded: id, version, outcomes and the block.yaml each came from, then a 'not loaded' line per block it skipped; reads the running control plane and never starts it (exit 1 when it isn't running)",
        "       sindri setup [--json]   where setting Sindri up stands: one line per step (repo, profile, recipes, mcp, map, sources) with what is true now; reads the running control plane and never starts it, and changes nothing; exit 0 when every step is done, 1 when one is still to do, waits for you or failed (or Sindri isn't running), 2 on an error",
        "       sindri doctor [--dev] [--json]  lease, ledger, views, profile, api, temporal and context checks, and the pinned harness probe; runs without the control plane",
        "       sindri doctor --probe [--harness <name>]  this process's agent variables (names only), ancestry and harness version, as JSON",
        "       sindri index connect github   reads a read-only GitHub token at the terminal (not shown), checks it against every repo context.sources.github.repos lists, and only then stores it (OS keychain, else an owner-only file) and writes its pointer into the profile; a session passes the token with --token-env NAME, a wrong scope saves nothing (SND-INDEX-009, SND-INDEX-010)",
        "       sindri index connect slack    reads a read-only Slack bot token at the terminal (not shown), checks it against every channel context.sources.slack.channels lists (never a direct message), and only then stores it (OS keychain, else an owner-only file) and writes its pointer into the profile; a session passes the token with --token-env NAME, a wrong scope saves nothing (SND-INDEX-009, SND-INDEX-010, SND-INDEX-013)",
        "       sindri index connect linear   reads a read-only Linear API key at the terminal (not shown), checks it can read every team context.sources.linear.teams lists (at least one team when none is listed), and only then stores it (OS keychain, else an owner-only file; always the file for a loopback fixture url) and writes its pointer into the profile, plus the teams it reads (sorted) when the profile lists none; a session passes the token with --token-env NAME, a refused key or a team it cannot read saves nothing (SND-INDEX-009, SND-INDEX-010)",
        "       sindri onyx down --purge   needs a terminal: lists and, on your typed yes, deletes what an old `onyx up` left (its labelled containers and volumes, its keychain entry, the onyx/ directory)",
        "       sindri repo status [<path>] [--nudge] [--json]   whether a repo (default: the working directory's, a worktree resolves to its main checkout) is in the profile; exit 0 onboarded, 1 not (or no profile, or outside git), 2 error; --nudge prints one line when the repo is not onboarded and nothing otherwise, always exits 0; read-only, runs without the control plane",
        "       sindri sandbox learn off [--repo <repo>] [--json]   end network learn mode early for a repo, or every repo without --repo: a tightening, so no approval; the next launch plans enforce mode (exit 0 done, 1 not running, 2 refused or invalid)",
        "       sindri mcp register [--repo NAME] [--providers claude,codex,cursor|all] [--apply] [--json]   the per-repo registration of /sindri/mcp for Claude Code, Codex and Cursor (Claude Code alone without --providers; --apply writes them)",
        "       sindri context query <text> [--node K | --item I | --symbol S | --diff BASE..HEAD [--repo R]] [--depth N] [--hops H] [--concept ID] [--budget N (ignored)] [--draft | --map-version V] [--limit N] [--offset N] [--json]   cited context from the running control plane; --limit/--offset read only that page of ranked records, none = the whole answer (exit 1: not running, unknown anchor, refused)",
        "       sindri context show <key> [--json]   one map node (a key, alias or name), its aliases and edges (exit 1: unknown or ambiguous, no map)",
        "       sindri context neighbors <key> [--depth N] [--json]   the nodes within N edges (0-4, default 1) either way",
        "       sindri context path <a> <b> [--json]   the shortest path of at most 8 edges between two nodes",
        "       sindri context eval probes [--file F] [--json]   ask each probe, print precision@5 and citation correctness beside the baseline run (exit 1: regressed, SND-CONTEXT-038; exit 2: a probe's query failed, nothing saved)",
        "       sindri context eval map [--json]         node and link precision on your accept/reject decisions, and the unmapped rate",
        "       sindri context eval purge [--all]        delete eval reports and the as-of map cache older than 90 days (--all: every one, probe baselines too)",
        "       sindri context eval backtest [--arms a,b|all] [--since D] [--until D] [--limit N] [--detach] [--json]   (a job)",
        "       sindri context sources status [--json]   each context source's state and whether sessions may read context",
        "       sindri context map import <file>   check a map file, show its hash, and make it the current map",
        "       sindri context map export [<path>] [--json]   write the current map under $AW_SINDRI_HOME/context/exports/",
        "       sindri context map status [--anchor <key>] [--json]   the current map version and its counts, then how it was published or why it is held for the code index (state: held, overdue, published, published-without-waiting, published-stale, published-by-hand; with --anchor, the lenses' coverage of that node) (exit 1: no map yet, SND-CONTEXT-030)",
        "       sindri context map review [--list] [--limit N] [--json]   the draft's review queue; at a terminal, the loop (bulk accept, then accept / reject / rename / move / skip each item); with --list, --limit or --json, the queue, read-only",
        "       sindri context map review accept|reject <node|edge:id> | rename <node> <name> | move <node> --under <node> | --undo <id>[,<id>…] | --drop <id> | --repoint <id> --to <node> | --accept-deterministic   one reversible decision (terminal or app)",
        "       sindri context map review --history [--limit N] | --export [<path>] | --apply <file> | merge <node> --into <node> | add <node> <name> [--under <node>] | delete <node>   each is sent at once, from a human or an agent session",
        "       sindri context map promote       make the latest draft current when nothing is left to decide (SND-CONTEXT-046); from a human or an agent session, with no challenge",
        "       sindri context map propose <file> [--json]   a scoping run's surfaces (run, repo, surfaces) as proposals in the draft; map proposals --run <id> reads where they stand",
        "       sindri context map build [--detach] [--json]   propose the map from the repo into a draft as a job and follow it (Ctrl-C cancels the job, a second Ctrl-C leaves); --detach prints the job id and returns (exit 0 succeeded, 1 failed or cancelled, 2 refused; SND-CONTEXT-040: the heavy-job lock stayed busy)",
        "       sindri repo add <path> [--name <name>] [--detach] [--json]   add a repo to the profile as a job and follow it (the app's Add repo calls the same route; Ctrl-C cancels the job, a second Ctrl-C leaves); the path is a git checkout, its main checkout is added; the profile then waits for your approval (exit 0 added, 1 failed or Sindri not running, 2 refused: SND-SETUP-001 not a repo folder, SND-SETUP-002 already added or the name is taken)",
        "       sindri repo onboard [<path>] [--detach] [--json]   onboard a repo of the profile by hand (default: the working directory's) as a job and follow it: its hook step and 'repo.onboarded'; the setup service does the same on its own when a repo is added; never edits the profile (exit 0 onboarded, 1 failed or Sindri not running, 2 refused: SND-SETUP-004 the profile does not name that repo)",
        "       sindri context map refresh [--detach] [--json]   build the map, let the cleanup agent settle its review queue and promote it, as a job, with no human step (the context-map-refresh service does this when a mapped repo's checkout moves along its default branch); exit codes as build",
        "       sindri context pin set <name> [--id ID] [--summary T] [--alias W]... [--feature K]... [--clear-aliases] [--clear-features] [--if-hash H] [--detach] [--no-start] [--json]   pin a concept in the profile's index.concepts as a job and follow it (the app's Pin this calls the same route): an omitted flag keeps the stored value, --alias or --feature replaces the list, --clear-* empties it; it never approves, it prints the hash to run 'profile approve' with; an agent session may run it (exit 0 written, 1 failed, Sindri not running or a session refused, 2 invalid input; --if-hash: the profile moved, SND-PROFILE-003)",
        "       sindri context pin set --from-file <list.txt> [--if-hash H] [--detach] [--no-start] [--json]   pin a pasted list in one write: one concept per line (Name: definition), or blocks with a blank line between, bullets dropped, a trailing (also: word, word) gives the words; the first 100 are taken; a line with no name writes nothing (SND-CONTEXT-177)",
        "       sindri context pin remove <id> [--with-folder-rules] [--if-hash H] [--detach] [--no-start] [--json]   unpin a concept; refused while it has paths, dependsOn or owns unless --with-folder-rules (SND-CONTEXT-175); never approves",
        "       sindri context pin list [--json]   the profile's pins (id, name, words, features, where each is set) and the live profile hash to pass to --if-hash; runs without the control plane",
        "       sindri context map whole [--detail auto|nodes|areas] [--area <key>] [--locate <key>]... [--map-version V | --draft] [--repo R] [--json]   the whole map in one read: every node and edge when it fits 500 nodes, else one line per feature area with the edges between areas; --area opens one area in full; --locate names the area of a key",
        "       sindri context lenses <anchor>... [--depth <0-4>] [--hops <state,flow,dependency,component>] [--draft | --map-version V] [--json]   the intent, product and code lenses of one or more nodes, with conflicts and coverage",
        "       sindri context subgraph <key>... [--keys-from <file|->] [--depth <0-4>] [--map-version V] [--json]   the bands, edges, conflicts and coverage of up to 1000 nodes and what they reach; unknown keys are listed as missing",
        "       sindri context page list [--suggested] [--concept C] [--repo R] [--json]   the pages a person named, each with its actions and the concepts they express and whether code was found; --suggested lists the pages the map offers that nobody named (exit 1: not running, no map, unknown concept or repo)",
        "       sindri context page set <name> [--id ID] [--repo R] [--surface KEY] [--action \"Name[=KEY][->c1,c2]\"]... [--if-hash H] [--dry-run] [--detach] [--no-start] [--json]   name a page in the profile's index.pages as a job and follow it: it replaces the page with that id by what the flags say (every action gets an id); --action takes the action's name, then =KEY for its map action, then -> and the concepts it expresses (a pin's or a map concept's id, or an exact name); --surface and the action keys must be in the current map; --dry-run checks exactly as a write does and prints the rows that would change; it never approves, it prints the hash to run 'profile approve' with; an agent session may run it (exit 0 written, 1 an unknown concept or key, no map, Sindri not running or a session refused, 2 invalid input or a refused write)",
        "       sindri context page set --from-file <pages.yaml> [--if-hash H] [--dry-run] [--detach] [--no-start] [--json]   set every page of a file in one write: the profile's own 'index: pages:' shape, or a bare 'pages:' list",
        "       sindri context page remove <id> [--if-hash H] [--detach] [--no-start] [--json]   remove the page with that id (SND-CONTEXT-257 when there is none, with the nearest ids); never approves",
        "       sindri context search <words> [--limit N] [--area <key>] [--repo R] [--map-version V | --draft] [--json]   ranked full-text search over the map: node labels, file paths, record titles, decision wording and quotes, best match first (default 50 hits, at most 200; the last word also matches as a prefix)",
        "       sindri context history <anchor>... [--since T] [--before T] [--draft | --map-version V] [--json]   the stored records, decisions and landed changes behind one or more nodes; --before cuts them to the world as of that time (T: RFC 3339 or YYYY-MM-DD)",
        "       sindri code-index status [--repo R] [--json]   each repo's code index: state, commit, layers and counts (exit 1 when a repo is not ok)",
        "       sindri code-index symbols <query> [--repo R] [--prefix] [--concept C] [--json]   symbols by name, path, path#name or ref (exact), or by name prefix; --concept C only those of one concept pin",
        "       sindri code-index callers|callees <ref> [--depth 1..8] [--repo R] [--json]   the edges into or out of a symbol, each with its basis, confidence and coverage (partial reads 'none found', never 'none')",
        "       sindri context code <anchor>... [--draft | --map-version V] [--json]   the files, tests, data things and schema files of one or more nodes, with a lexical search of the repo at the map's commit",
        "       sindri context filemap --repo <repo> [--path <dir>] [--unmapped] [--draft] [--json]   a directory's children with their map status; filemap accept|reject <link-id> decides a suggested file link",
        "       sindri context sources sync [<source>] [--detach] [--json]   sync the intent sources now as a job and follow it (Ctrl-C cancels the job, a second Ctrl-C leaves); --detach prints the job id and returns; a second start while one runs is SND-JOB-409",
        "       sindri wf validate <file> [--json]   check a workflow graph in-process: findings naming node and field with the fix, or its hash (exit 0 pass, 1 findings, 2 error)",
        "       sindri wf blocks [--json]   the block types a workflow can use, grouped as the picker shows them, with config fields, outputs and branches (exit 0 ok, 1 not running)",
        "       sindri wf docs [<question words>] [--page <slug>] [--json]   search the workflow docs, read one page (--page block-schedule) or list the pages (exit 0 ok, 1 not running, 2 unknown page)",
        "       sindri wf run <slug> [--payload JSON] [--json]   start a run of the workflow's active revision by hand: started, queued or skipped by its concurrency (exit 0 ok, 1 not running, 2 refused)",
        "       sindri wf list [--json]   the workflows that are not archived: slug, name, active revision, who saved the newest (exit 0 ok, 1 not running)",
        "       sindri wf show <slug> [--json]   one workflow: the revision it runs, who saved its newest, its nodes and edges (--json adds the spec and node positions; exit 0 ok, 1 not running, 2 unknown)",
        "       sindri wf runs <slug> [--json]   a workflow's newest 50 runs, newest first, with status and trigger (exit 0 ok, 1 not running, 2 unknown)",
        "       sindri wf run-show <run> [--json]   one run with what each node did (exit 0 ok, 1 not running, 2 unknown)",
        "       sindri wf create <slug> (--template <name> | --file <spec.json>) [--json]   make a workflow, off, at revision 1, from a starter template or a spec file (exit 0 ok, 1 not running, 2 refused)",
        "       sindri wf edit <slug> --base <revision> (--ops <json> | --ops-file <file> | --file <spec.json>) [--json]   edit by ops (all apply or none) or replace the whole graph; a stale --base is refused with the current revision",
        "       sindri wf validate --slug <slug> [--revision <n>] [--json]   check a stored workflow as if it were being activated (the file form above runs in process)",
        "       sindri wf activate <slug> [--revision <n>] [--json]   turn the workflow's triggers on at a revision (the newest by default) after the activation checks",
        "       sindri wf pause <slug> [--json]   turn the workflow's triggers off; revisions stay and runs in flight keep going",
        "       sindri wf delete <slug> [--json]   archive the workflow: it leaves the list and turns off for good; revisions and runs stay readable",
        "       sindri wf cancel <run> [--json]   ask a run in flight to stop (exit 0 ok, 1 not running, 2 refused)",
        "       sindri wf takeover <run> <node> [--item <index>] [--json]   take the run_agent node the run waits on over: its timeout pauses and only you report it (exit 0 ok, 1 not running, 2 refused)",
        "       sindri wf handback <run> <node> [--item <index>] [--json]   hand a taken-over run_agent node back: its timeout resumes with what was left (exit 0 ok, 1 not running, 2 refused)",
        "       sindri answer <run>/<node> (--text T | --choice C) [--item N] [--json]   answer the question an ask_owner node waits on, as yourself (the timeline shows your actor: human:<client>, session:launch:<launch id> or session:<client>); the node must be waiting and a choice must be one it offers (exit 0 answered, 1 not running, 2 refused)",
        "       sindri workflow takeover <address> [--nonce <n>] [--json]   take the instance over: its timer pauses",
        "       sindri workflow handback <address> [--nonce <n>] [--json]   hand a taken-over instance back: its timer resumes",
        "       sindri takeover <run> <node> [--item <index>] [--json]   short form of 'wf takeover'",
        "       sindri handback <run> <node> [--item <index>] [--json]   short form of 'wf handback'",
        "       sindri workflow complete <address> --run <token> --outcome <o> [--output <fact>=<file>]... [--nonce <n>] [--json]   report an open desk run (exit 0 applied, 1 not running, 2 invalid, refused or error)",
    ];

    internal static readonly string Text = string.Join('\n', [.. _verbs, "exit codes: 0 ok, 1 attention needed, 2 error"]);
}
